<script setup lang="ts">
import { newRequestId } from '../domain/requestId'
import { computed, ref, watch } from 'vue'
import type { GameSession, GameAction } from '../api/types'
import { remaining } from '../domain/sessionTime'
const props = defineProps<{ session: GameSession; busy: boolean; elapsed: number }>()
const emit = defineEmits<{ action: [action: GameAction] }>()
const target = ref('')
const me = computed(() => props.session.participants.find(p => p.id === props.session.me))
const runners = computed(() => props.session.participants.filter(p => p.role === 'runner' && p.state === 'active'))
const allowed = computed(() => props.session.status === 'running' && props.session.phase === 'hunt' && me.value?.state === 'active')
const names = (id: string | undefined) => props.session.participants.find(p => p.id === id)?.name || 'Unbekannt'
const reportNames = { pending: 'Bestätigungen ausstehend', confirmed: 'Fang bestätigt', rejected: 'Fang abgelehnt', expired: 'Fangmeldung abgelaufen' }
const huntNames = { active: 'Aktiv', completed: 'Alle Pings verbraucht', expired: 'Pingfrist abgelaufen', target_caught: 'Ziel gefangen', game_finished: 'Spiel beendet' }
watch(runners, list => { if (!list.some(p => p.id === target.value)) target.value = list[0]?.id || '' }, { immediate: true })
function request(path: string, body: Record<string, unknown>, idempotent = false) { emit('action', { path, body: idempotent ? { ...body, requestId: newRequestId() } : body }) }
</script>
<template><section class="panel gameplay-actions"><h2>Spielaktionen</h2><p v-if="me?.state === 'eliminated'" role="status" class="simulator-notice">Du wurdest gefangen und bist ausgeschieden.</p><p v-if="session.phase === 'headstart'" class="muted">Fänge und Speedhunts sind erst nach dem ersten Silent-Ping erlaubt.</p><template v-if="me?.role === 'hunter'"><p>Gemeinsame Speedhunts: <strong data-testid="speedhunt-quota">{{ session.speedhuntsRemaining }}</strong></p><label for="hunt-target">Gejagten auswählen</label><select id="hunt-target" v-model="target" :disabled="busy || !allowed"><option v-for="p in runners" :key="p.id" :value="p.id">{{ p.name }}</option><option v-if="!runners.length" value="">Keine aktiven Gejagten</option></select><div class="card-actions"><button :disabled="busy || !allowed || !target" @click="request('/play/catches', { targetId: target }, true)">Fang melden</button><button class="secondary" :disabled="busy || !allowed || !target || !session.speedhuntsRemaining || session.speedhunt?.status === 'active'" @click="request('/play/speedhunts', { targetId: target }, true)">Speedhunt starten</button></div></template><section v-if="session.speedhunt" class="speedhunt-info"><h3>Speedhunt <span v-if="session.speedhunt.targetId">auf {{ names(session.speedhunt.targetId) }}</span></h3><p>{{ huntNames[session.speedhunt.status] }}</p><p v-if="session.speedhunt.status === 'active'">Nächster Ping spätestens in {{ remaining(session, session.speedhunt.expiresAt, elapsed) }}</p><template v-if="me?.role === 'hunter'"><p>{{ session.speedhunt.remainingPings }} von {{ session.speedhunt.pingLimit }} Pings verbleiben</p><button :disabled="busy || !allowed || session.speedhunt.status !== 'active'" @click="request(`/play/speedhunts/${session.speedhunt.id}/pings`, { expectedPingNumber: session.speedhunt.nextPingNumber }, true)">Nächsten Speedhunt-Ping anfordern</button></template><p v-else class="muted">{{ session.speedhunt.targetId ? 'Das Speedhunt-Ziel wird gemäß Spielregel angezeigt.' : 'Das Ziel bleibt gemäß Spielregel verborgen.' }}</p></section><section v-if="session.catches.length" class="catch-list"><h3>Fangmeldungen</h3><article v-for="report in session.catches" :key="report.id" class="catch-card"><strong>{{ names(report.targetId) }}</strong><p>{{ reportNames[report.status] }}</p><small class="muted">Spielleitung: {{ report.adminConfirmed === null ? 'offen' : report.adminConfirmed ? 'bestätigt' : 'abgelehnt' }} · Gejagter: {{ report.runnerConfirmed === null ? 'offen' : report.runnerConfirmed ? 'bestätigt' : 'abgelehnt' }}</small><div v-if="report.status === 'pending' && report.targetId === session.me && report.runnerConfirmed === null" class="card-actions"><button :disabled="busy || !allowed" @click="request(`/play/catches/${report.id}/runner-decision`, { confirm: true })">Fang bestätigen</button><button class="secondary" :disabled="busy || !allowed" @click="request(`/play/catches/${report.id}/runner-decision`, { confirm: false })">Fang ablehnen</button></div></article></section></section></template>
